    private long integer(Object value, String label) { assertTrue(value instanceof Integer || value instanceof Long, label + " must have an integral JSON carrier: " + value); return ((Number) value).longValue(); }
    private Context context(boolean inlining) { return Context.newBuilder("thc").allowExperimentalOptions(true).option("compiler.Inlining", Boolean.toString(inlining)).option("engine.BackgroundCompilation", "false").option("engine.MultiTier", "false").option("engine.CompilationFailureAction", "Throw").build(); }
    @FunctionalInterface private interface Action { void run(Language language) throws Exception; }
    private void withLanguage(boolean inlining, Action action) throws Exception { try (var context = context(inlining)) { context.initialize("thc"); context.enter(); try { action.run(TruffleLanguage.LanguageReference.create(Language.class).get(null)); } finally { context.leave(); } } }
    private void validateMode(Map<String, Object> provenance, String architecture) {
        assertTrue(provenance.keySet().containsAll(List.of("stages", "modelRows", "modelByteOrder", "nativeRows", "nativeByteOrder", "modelMatched")), "Missing explicit DoubleX2 preparation mode fields"); assertEquals(4384L, integer(provenance.get("modelRows"), "modelRows"), "modelRows must be exactly 4384"); assertEquals("little", provenance.get("modelByteOrder"), "DoubleX2 model byte order");
        // Use the executing host, not a producer architecture in the manifest.
        if (List.of("arm64", "aarch64").contains(architecture.toLowerCase(Locale.ROOT))) { assertEquals(List.of("pre"), provenance.get("stages"), "ARM64 export-only Core stages"); for (var field : List.of("nativeRows", "nativeByteOrder", "modelMatched")) assertNull(provenance.get(field), "ARM64 export-only " + field + " must be explicitly null"); }
        else { assertEquals(List.of("pre", "post"), provenance.get("stages"), "Native Core stages"); assertEquals(4384L, integer(provenance.get("nativeRows"), "nativeRows"), "nativeRows must be exactly 4384"); assertEquals("little", provenance.get("nativeByteOrder"), "Native byte order"); assertEquals(true, provenance.get("modelMatched"), "Native/model agreement"); }
    }
    private Map<String, Object> read(File file) throws Exception { return (Map<String, Object>) Json.parse(Files.readString(file.toPath())); }
    private Map<String, Object> provenance() throws Exception {
        var provenance = read(new File(directory, "provenance.json")); validateMode(provenance, System.getProperty("os.arch")); assertEquals("doublex2-bytearray", provenance.get("vector"), "Exact Double memory provenance"); assertEquals(ByteOrder.LITTLE_ENDIAN, ByteOrder.nativeOrder(), "DoubleX2 bounded corpus requires a little-endian host"); assertEquals(true, provenance.get("positiveAuditsAccepted"));
        var files = new ArrayList<>((List<Map<String, String>>) provenance.get("sources")); files.addAll((List<Map<String, String>>) provenance.get("artifacts")); for (var file : files) { String hash = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(new File(root, file.get("path")).toPath()))); assertEquals(file.get("sha256"), hash, "Stale DoubleX2 memory source/artifact: " + file.get("path")); } return provenance;
    }
    private void visit(RootCallTarget target, Set<RootCallTarget> seen, List<RootCallTarget> result) { if (!seen.add(target)) return; var body = target.getRootNode(); var nodes = new ArrayList<Node>(); nodes.add(body); if (body instanceof BytecodeRoot bytecode) for (var instruction : bytecode.getBytecodeNode().getInstructions()) for (var arg : instruction.getArguments()) if (arg.getKind() == Instruction.Argument.Kind.NODE_PROFILE) { var cached = arg.asCachedNode(); if (cached != null) nodes.add(cached); } for (var node : nodes) for (var call : NodeUtil.findAllNodeInstances(node, DirectCallNode.class)) if (call.getCurrentCallTarget() instanceof RootCallTarget active && active.getRootNode() instanceof GuestRoot) visit(active, seen, result); result.add(target); }
    private List<RootCallTarget> activeTargets(RootCallTarget target) { var result = new ArrayList<RootCallTarget>(); visit(target, Collections.newSetFromMap(new IdentityHashMap<>()), result); return result; }
    private void valid(RootCallTarget target, String label) throws Exception { assertEquals(true, target.getClass().getMethod("isValidLastTier").invoke(target), label); }
    @Test public void nativeMemoryCoreHasExactCompiledEntriesWithInlining() throws Exception { nativeCore(true); }
    @Test public void nativeMemoryCoreHasExactCompiledEntriesWithoutInlining() throws Exception { nativeCore(false); }
    private Map<String, Object> map(Object... items) { var result = new LinkedHashMap<String, Object>(); for (int i = 0; i < items.length; i += 2) result.put((String) items[i], items[i + 1]); return result; }
    private Map<String, Object> with(Map<String, Object> original, String key, Object value) { var result = new LinkedHashMap<>(original); result.put(key, value); return result; }
    private record Change(String field, Object value) {}
    @Test public void preparationModeRejectsCorruptionAndNativeDowngrades() {
        var nativeMode = map("stages", List.of("pre", "post"), "modelRows", 4384L, "modelByteOrder", "little", "nativeRows", 4384L, "nativeByteOrder", "little", "modelMatched", true); var exported = new LinkedHashMap<>(nativeMode); exported.putAll(map("stages", List.of("pre"), "nativeRows", null, "nativeByteOrder", null, "modelMatched", null));
        var nativeBad = List.of(new Change("stages", List.of()), new Change("stages", List.of("pre")), new Change("stages", List.of("post", "pre")), new Change("stages", List.of("pre", "post", "post")), new Change("nativeRows", null), new Change("nativeRows", 4383L), new Change("nativeRows", 4384.0), new Change("nativeRows", 4384.5), new Change("nativeRows", true), new Change("nativeRows", "4384"), new Change("nativeByteOrder", null), new Change("nativeByteOrder", "big"), new Change("modelMatched", null), new Change("modelMatched", false));
        var exportBad = List.of(new Change("stages", List.of()), new Change("stages", List.of("pre", "post")), new Change("stages", List.of("pre", "pre")), new Change("nativeRows", 0L), new Change("nativeRows", 4384L), new Change("nativeByteOrder", "little"), new Change("modelMatched", true), new Change("modelMatched", false)); var common = List.of(new Change("modelRows", 4383L), new Change("modelRows", 4384.0), new Change("modelRows", 4384.5), new Change("modelRows", true), new Change("modelRows", "4384"), new Change("modelByteOrder", "big"));
        for (var architecture : List.of("amd64", "x86_64", "riscv64", "arm64", "aarch64")) { boolean arm = List.of("arm64", "aarch64").contains(architecture); var accepted = arm ? exported : nativeMode; validateMode(accepted, architecture); assertThrows(AssertionError.class, () -> validateMode(arm ? nativeMode : exported, architecture), architecture + " cannot silently change preparation modes"); var changes = new ArrayList<>(common); changes.addAll(arm ? exportBad : nativeBad); for (var change : changes) assertThrows(AssertionError.class, () -> validateMode(with(accepted, change.field, change.value), architecture), architecture + "/" + change.field + "=" + change.value); for (var field : accepted.keySet()) { var missing = new LinkedHashMap<>(accepted); missing.remove(field); assertThrows(AssertionError.class, () -> validateMode(missing, architecture), architecture + "/missing " + field); } }
        assertThrows(AssertionError.class, () -> validateMode(with(exported, "toolchain", map("architecture", "aarch64")), "amd64"));
    }
    @Test public void genuineExportedVectorBoundariesRemainRejected() throws Exception { var provenance = provenance(); for (var stage : (List<String>) provenance.get("stages")) for (var backend : List.of("ast", "bytecode")) withLanguage(true, language -> { var module = read(new File(directory, stage + "-core/SimdDoubleX2ByteArray.json")); for (var name : List.of("vectorArgument", "readTupleEscape", "readVectorEscape")) { var linked = CoreModules.reachable(module, name); assertThrows(RuntimeFault.class, () -> { if (backend.equals("ast")) new Program(language, linked); else new BytecodeProgram(language, linked); }, stage + "/" + backend + "/" + name); } }); }
    private void checkFault(PolyglotException error, boolean diagnostic, String label) { String message = error.getMessage() == null ? "" : error.getMessage(); assertTrue(message.contains("unboxed-tuple (host result)"), label + ": " + message); assertEquals(diagnostic, message.contains("Diagnostic unsupported path reached:"), label); }
    @Test public void publicHostTupleResultsRejectAtLoadOrTrapBeforeArgumentNormalization() throws Exception { var provenance = provenance(); for (var stage : (List<String>) provenance.get("stages")) for (var backend : List.of("ast", "bytecode")) try (var context = context(true)) { var module = read(new File(directory, stage + "-core/SimdDoubleX2ByteArray.json")); for (var family : List.of("vector", "scalar")) for (var operation : List.of("Read", "Write")) { int arity = operation.equals("Read") ? 4 : 5; String name = family + operation + "Worker"; for (boolean diagnostic : new boolean[] {false, true}) { String label = stage + "/" + backend + "/" + name + "/diagnostic=" + diagnostic; String request = Json.stringify(map("entry", name, "backend", backend, "diagnosticUnsupported", diagnostic, "modules", List.of(module))); if (!diagnostic) checkFault(assertThrows(PolyglotException.class, () -> context.eval("thc", request), label), false, label); else { var entry = context.eval("thc", request); assertTrue(entry.canExecute(), label); var zero = new Object[arity]; Arrays.fill(zero, 0L); var bad = zero.clone(); bad[0] = "invalid host argument"; for (var input : List.of(zero, bad, new Object[0])) checkFault(assertThrows(PolyglotException.class, () -> entry.execute(input), label), true, label); } } } } }
    private final List<Long> rawBits = List.of(0L, Long.MIN_VALUE, 1L, Long.MIN_VALUE + 1, 0x000fffffffffffffL, 0x800fffffffffffffL, 0x0010000000000000L, 0x8010000000000000L, 0x3ff0000000000000L, 0xbff0000000000000L, 0x7fefffffffffffffL, 0xffefffffffffffffL, 0x7ff0000000000000L, 0xfff0000000000000L, 0x7ff8123456789abcL, 0xfff8abcdef012345L);
    private final List<Long> finiteEdges = List.of(-(1L << 40), -(1L << 32) - 1, -1L, 0L, 1L, (1L << 32) - 1, (1L << 40) - 1, 1L << 40);
    private final List<String> operations = List.of("Unit", "Index", "Read", "Write", "GraphIndex", "GraphStore");
    private String operation(String name) { String result = null; for (var op : operations) if (name.equals("vector" + op + "Case") || name.equals("scalar" + op + "Case")) { if (result != null) throw new IllegalArgumentException(); result = op; } return Objects.requireNonNull(result); }
    /** Independent exact inventory excludes native-only signaling NaNs. */
    private Set<List<Long>> expectedCases(String name) {
        String op = operation(name); int offsets = name.startsWith("vector") ? 4 : 7; var patterns = new ArrayList<List<Long>>();
        if (op.startsWith("Graph")) for (int lane = 0; lane <= 1; lane++) for (long value : finiteEdges) { var lanes = new ArrayList<>(List.of(-31L, 127L)); lanes.set(lane, value); patterns.add(lanes); }
        else for (int i = 0; i < rawBits.size(); i++) patterns.add(List.of(rawBits.get(i), rawBits.get((i + 5) % rawBits.size())));
        int selectors = switch (op) { case "Unit" -> 4; case "Index", "Read" -> 2; case "Write", "GraphStore" -> 64; default -> 0; }; var result = new LinkedHashSet<List<Long>>();
        for (int i = 0; i < patterns.size(); i++) { var input = new ArrayList<Long>(); input.add((long) (i % offsets)); input.addAll(patterns.get(i)); if (selectors == 0) result.add(input); else for (long s = 0; s < selectors; s++) { var row = new ArrayList<>(input); row.add(s); result.add(row); } } return result;
    }
    private void put(byte[] bytes, int at, long value) { for (int b = 0; b <= 7; b++) bytes[at + b] = (byte) (value >>> (8 * b)); }
    private long word(byte[] bytes, int at) { long result = 0; for (int b = 0; b <= 7; b++) result |= ((long) bytes[at + b] & 255) << (8 * b); return result; }
    /** Explicit little-endian bit movement retains all64 lane bits. */
    private long independentExpected(String name, List<Long> input) {
        String op = operation(name); boolean graph = op.startsWith("Graph"); int address = (int) (input.getFirst() * (name.startsWith("vector") ? 16 : 8)); var bytes = new byte[64]; for (int i = 0; i <= 15; i++) { long value = 0x89abcdefL + i * 0x01030507L; for (int b = 0; b <= 3; b++) bytes[4 * i + b] = (byte) (value >>> (8 * b)); } var values = input.subList(1, 3); for (int lane = 0; lane <= 1; lane++) put(bytes, address + 8 * lane, graph ? Double.doubleToRawLongBits(values.get(lane).doubleValue()) : values.get(lane));
        if (op.equals("Unit")) { int selector = input.get(3).intValue(); return word(bytes, address + 8 * (selector % 2)) ^ (selector == 3 ? Long.MIN_VALUE : 0L); } if (op.equals("Index") || op.equals("Read")) return word(bytes, address + 8 * input.get(3).intValue()); long selected = op.equals("GraphIndex") ? 0L : (long) bytes[input.get(3).intValue()] & 255; if (op.equals("Write")) return values.get(0) ^ values.get(1) ^ selected;
        long score = values.get(0) * 3 + values.get(1) * 5; assertTrue(graph); assertTrue(Math.abs(values.get(0) * 3) + Math.abs(values.get(1) * 5) < (1L << 44)); double fp = values.get(0).doubleValue() * 3.0 + values.get(1).doubleValue() * 5.0; assertEquals(score, (long) fp, "Finite checksum binary64 exactness"); return op.equals("GraphIndex") ? score : score * 257 + selected;
    }
    private record Key(String name, List<Long> input) {}
    private Map<Key, Long> rows(String filename) throws Exception { var lines = Files.readAllLines(new File(directory, filename).toPath()); var result = new LinkedHashMap<Key, Long>(); for (var line : lines) { var parts = line.split("\t", -1); var values = new ArrayList<Long>(); for (int i = 1; i < parts.length; i++) { long value = Long.parseLong(parts[i]); assertEquals(parts[i], Long.toString(value), "Canonical oracle integer"); values.add(value); } result.put(new Key(parts[0], new ArrayList<>(values.subList(0, values.size() - 1))), values.getLast()); } assertEquals(lines.size(), result.size(), "Duplicate corpus rows"); return result; }
    private void check(boolean compiled, String stage, String backend, String name, boolean inlining, List<List<Long>> cases, Map<Key, Long> expected, ExecutableProgram program, RootCallTarget host, Object closure, RootCallTarget target, long callCount, List<RootCallTarget> targets, Language language) throws Exception {
        for (var input : cases) { String label = stage + "/" + backend + "/" + name + "/" + input + "/inlining=" + inlining; long before = ((Number) program.diagnostics().get("compiledEntries")).longValue(); assertEquals(expected.get(new Key(name, input)), Calls.target(host, new Object[] {closure, input.toArray()}), label);
            if (compiled) { assertEquals(before + callCount, ((Number) program.diagnostics().get("compiledEntries")).longValue(), label + " compiled guest entries"); var active = activeTargets(target); assertEquals(targets.size(), active.size(), label + " active target count"); for (var candidate : active) { boolean present = false; for (var old : targets) if (old == candidate) present = true; assertTrue(present, label + " active identities"); } for (var old : targets) valid(old, label); var calls = new ArrayList<DirectCallNode>(); for (var call : NodeUtil.findAllNodeInstances(host.getRootNode(), DirectCallNode.class)) if (call.getCallTarget() == target) calls.add(call); assertFalse(calls.isEmpty(), label + " selected entry"); for (var call : calls) assertSame(target, call.getCurrentCallTarget(), label + " selected identity"); }
            var state = language.getHandoffState().get(); assertEquals(0, state.getResults().getDepth()); assertEquals(0, state.getResults().retainedReferences()); assertEquals(0, state.getArguments().getDepth()); assertEquals(0, state.getArguments().retainedReferences());
        }
    }
    private void nativeCore(boolean inlining) throws Exception {
        var provenance = provenance(); var stages = (List<String>) provenance.get("stages"); var expected = rows("expected.tsv"); assertEquals(4384, expected.size()); for (var e : expected.entrySet()) assertEquals(independentExpected(e.getKey().name, e.getKey().input), e.getValue().longValue(), "Independent bytes: " + e.getKey()); if (provenance.get("nativeRows") != null) { assertEquals(expected, rows("oracle.tsv")); assertEquals((long) expected.size(), integer(provenance.get("nativeRows"), "nativeRows")); }
        var entries = (List<Map<String, Object>>) provenance.get("entries"); var names = new HashSet<String>(); for (var family : List.of("vector", "scalar")) for (var op : operations) names.add(family + op + "Case"); assertEquals(12, entries.size()); var observedNames = new HashSet<Object>(); var declared = new ArrayList<Key>(); for (var entry : entries) { observedNames.add(entry.get("name")); for (var row : (List<List<Object>>) entry.get("cases")) { var input = new ArrayList<Long>(); for (var value : row) input.add(integer(value, "declared input")); declared.add(new Key((String) entry.get("name"), input)); } } assertEquals(names, observedNames); assertEquals(declared.size(), new HashSet<>(declared).size()); assertEquals(new HashSet<>(declared), expected.keySet()); var counts = (Map<String, Object>) provenance.get("expectedGuestCallsByEntry");
        for (var stage : stages) for (var backend : List.of("ast", "bytecode")) withLanguage(inlining, language -> { var module = read(new File(directory, stage + "-core/SimdDoubleX2ByteArray.json")); for (var entry : entries) { String name = (String) entry.get("name"); long rawArity = integer(entry.get("arity"), name + " arity"); assertTrue(rawArity >= 1 && rawArity <= 5); int arity = (int) rawArity; var cases = new ArrayList<List<Long>>(); for (var row : (List<List<Object>>) entry.get("cases")) { var input = new ArrayList<Long>(); for (var value : row) input.add(integer(value, name + " input")); cases.add(input); } assertFalse(cases.isEmpty()); for (var input : cases) assertEquals(arity, input.size()); var offsets = new HashSet<Long>(); for (long offset = 0; offset <= (name.startsWith("vector") ? 3 : 6); offset++) offsets.add(offset); String op = operation(name); assertEquals(op.equals("GraphIndex") ? 3 : 4, arity, name + " exact arity"); var wanted = expectedCases(name); assertEquals(wanted.size(), cases.size(), name + " exact rows"); assertEquals(wanted, new HashSet<>(cases), name + " exact portable domain (sNaNs excluded)"); var actualOffsets = new HashSet<Long>(); for (var input : cases) actualOffsets.add(input.getFirst()); assertEquals(offsets, actualOffsets, name + " safe offsets");
            var linked = with(CoreModules.reachable(module, name), "instrument", true); ExecutableProgram program = backend.equals("ast") ? new Program(language, linked) : new BytecodeProgram(language, linked); var host = program.hostEntryTarget(arity); var closure = program.entryValue(name); var target = program.entryTarget(name); long callCount = integer(counts.get(name), name + " guest count");
            // Historical structural counts include the retained raw-index runRW lambda.
            assertEquals(op.equals("Unit") ? 2L : op.equals("Index") ? 4L : 3L, callCount); assertEquals(callCount, integer(((Map<String, Object>) provenance.get("checkedGuestCallsByStage")).get(stage + "/" + name), stage + "/" + name + " checked count")); check(false, stage, backend, name, inlining, cases, expected, program, host, closure, target, callCount, List.of(), language); var targets = activeTargets(target); assertEquals((int) callCount, targets.size(), stage + "/" + backend + "/" + name + " guest roots"); for (var t : targets) { t.getClass().getMethod("compile", boolean.class).invoke(t, true); valid(t, "initial installation"); } check(true, stage, backend, name, inlining, cases, expected, program, host, closure, target, callCount, targets, language); for (var counter : List.of("unsupportedTraps", "blackholes")) assertEquals(0L, ((Number) program.diagnostics().get(counter)).longValue(), counter);
        } });
    }
